from pathlib import Path
import json,html,math
R=Path(__file__).resolve().parents[1];H=R/'hyperframes'
CSS='''@font-face{font-family:FilmSans;src:url('assets/FilmSans-Bold.ttf');font-weight:700}@font-face{font-family:FilmSans;src:url('assets/FilmSans-Regular.ttf');font-weight:400}*{box-sizing:border-box}#root{position:absolute;inset:0;font-family:FilmSans;color:#f4f1e9}.clip{position:absolute;inset:0;pointer-events:none}.panel{position:absolute;background:rgba(5,17,29,.88);border:1.5px solid rgba(241,143,49,.84);border-radius:8px;padding:20px 24px;box-shadow:0 10px 30px rgba(0,0,0,.18)}.label{font-size:28px;letter-spacing:2.6px;font-weight:700;color:#c2c9cb;line-height:1.25}.value{font-size:70px;line-height:1.08;font-weight:700;letter-spacing:-2px;font-variant-numeric:tabular-nums}.unit{position:absolute;right:24px;bottom:31px;font-size:28px;color:#c6cfd2;letter-spacing:.2px}.track{height:6px;background:#33434e;border-radius:2px;overflow:hidden;margin-top:13px}.fill{height:100%;background:#f89c38;transform-origin:left center}.dial svg{position:absolute;left:0;top:70px;width:340px;height:260px}.dial .value{position:absolute;top:245px;left:105px;width:130px;text-align:center;font-size:66px}.dial .unit{bottom:27px;left:0;right:0;text-align:center;font-size:28px}.dial .label{text-align:center}.dial .track{position:absolute;left:25px;right:25px;bottom:12px;margin:0}.compact .value{margin-top:8px}.compact .unit{top:94px;bottom:auto}#demo-speed .unit,#demo-gap .unit{top:145px;bottom:auto}.clock .value{font-size:53px;letter-spacing:-1px;margin-top:9px}.caption{position:absolute;left:108px;width:864px;text-align:center;top:1460px;font-size:59px;line-height:1.22;font-weight:700;letter-spacing:-1px}.caption span{display:inline-block;background:rgba(3,13,23,.86);padding:7px 17px 11px;border-radius:6px}.accent{color:#ffa84b}.caption em{font-style:normal;color:#ffa84b}'''
def dialsvg():
 s='<svg viewBox="0 0 340 260" aria-label="calibrated speedometer">'
 for v in range(0,141,10):
  th=math.radians(140+260*v/140);x=170+110*math.cos(th);y=144+110*math.sin(th);xx=170+(98 if v%20==0 else 104)*math.cos(th);yy=144+(98 if v%20==0 else 104)*math.sin(th)
  s+=f'<path d="M{x} {y} L{xx} {yy}" stroke="{("#f49b43" if v>=120 else "#bdc9ce")}" stroke-width="2"/>'
  if v in [0,70,140]:s+=f'<text x="{170+125*math.cos(th)}" y="{150+125*math.sin(th)}" text-anchor="middle" fill="#c5d1d4" font-size="28" font-family="FilmSans">{v}</text>'
 s+='<g id="hf-needle"><path d="M145 144 L265 144" stroke="#fdad50" stroke-width="5" stroke-linecap="round"/></g><circle cx="170" cy="144" r="8" fill="#f1cc92"/></svg>'
 return s
hud=f'''<template><style>{CSS}</style><div id="root" data-composition-id="hud" data-width="1080" data-height="1920">
<div id="clock-clip" class="clip" data-start="0" data-duration="2"><section id="hf-clock-panel" class="panel clock" style="left:108px;top:230px;width:365px;height:154px"><div class="label">LOCAL TIME</div><div id="hf-clock-value" class="value">02:17:00</div><div class="unit">AM</div></section></div>
<div id="dial-clip" class="clip" data-start="4" data-duration="2.5"><section id="hf-dial-panel" class="panel dial" style="left:618px;top:255px;width:340px;height:410px"><div class="label">VEHICLE SPEED</div>{dialsvg()}<div id="hf-dial-value" class="value">28</div><div class="unit">km/h</div><div class="track"><div id="hf-dial-bar" class="fill"></div></div></section></div>
<div id="speed-clip" class="clip" data-start="6.5" data-duration="3.5"><section id="hf-speed-panel" class="panel compact" style="left:108px;top:230px;width:340px;height:188px"><div class="label">VELOCITY</div><div id="hf-speed-value" class="value">53</div><div class="unit">km/h</div><div class="track"><div id="hf-speed-bar" class="fill"></div></div></section></div>
<div id="gap-clip" class="clip" data-start="10" data-duration="2.5"><section id="hf-gap-panel" class="panel compact" style="left:108px;top:230px;width:340px;height:188px"><div class="label">PURSUER</div><div id="hf-gap-value" class="value">13.0</div><div class="unit">m</div><div class="track"><div id="hf-gap-bar" class="fill"></div></div></section></div>
</div><script>
(()=>{{const C=window.HFComponents,tl=gsap.timeline({{paused:true}}),clock=new C.DigitalClock('#hf-clock-value'),dial=new C.SpeedometerOverlay({{value:'#hf-dial-value',needle:'#hf-needle',bar:'#hf-dial-bar'}}),speed=new C.AnimatedCounter('#hf-speed-value',{{initial:C.vehicleAt(6.5).speed_kmh,target:C.vehicleAt(10).speed_kmh,decimals:1}}),bar=new C.AnimatedProgressBar('#hf-speed-bar',{{max:140}}),gap=new C.PursuitDistanceHUD('#hf-gap-value','#hf-gap-bar');
[['#hf-clock-panel',.04,2],['#hf-dial-panel',4,6.5],['#hf-speed-panel',6.5,10],['#hf-gap-panel',10,12.5]].forEach(([sel,s,e])=>new C.CinematicHUDPanel(sel).animate(tl,s,e));
function draw(t){{const s=C.vehicleAt(t);clock.render(t);dial.render(s);speed.render(s.speed_kmh);bar.render(s.speed_kmh);gap.render(s);}}const driver={{t:0}};tl.to(driver,{{t:15,duration:15,ease:'none',onUpdate:()=>draw(driver.t)}},0);window.addEventListener('hf-seek',e=>draw(e.detail.time));draw(0);window.__timelines=window.__timelines||{{}};window.__timelines['hud']=tl;}})();
</script></template>'''
(H/'compositions/hud.html').write_text(hud)
caps=json.loads((R/'caption-timing.json').read_text());parts=[];tweens=[]
for j,c in enumerate(caps):
 boundaries=sorted(set([c['start'],c['end']]+[t for t in [3.2,4] if c['start']<t<c['end']]))
 for k,(st,en) in enumerate(zip(boundaries,boundaries[1:])):
  ident=f'cap-{j}-{k}';words=c['text'].split();text=' '.join(('<em>'+html.escape(w)+'</em>') if w.lower().strip('.,') in ['gas','followed','behind'] else html.escape(w) for w in words)
  top=350 if 3.2<=st<4 else 1460
  parts.append(f'<div id="{ident}-clip" class="clip" data-start="{st}" data-duration="{en-st}"><div id="{ident}" class="caption" data-layout-allow-caption-zone style="top:{top}px"><span>{text}</span></div></div>')
  tweens.append(f"tl.fromTo('#{ident}',{{opacity:0,y:12}},{{opacity:1,y:0,duration:.12,ease:'power3.out'}},{st});tl.to('#{ident}',{{opacity:0,duration:.08}},{max(st,en-.08)});")
(H/'compositions/captions.html').write_text(f'<template><style>{CSS}</style><div id="root" data-composition-id="captions" data-width="1080" data-height="1920">'+''.join(parts)+"</div><script>(()=>{const tl=gsap.timeline({paused:true});"+''.join(tweens)+"window.__timelines=window.__timelines||{};window.__timelines['captions']=tl;})();</script></template>")
HEAD='''<!doctype html><html lang="en"><head><meta charset="UTF-8"><script src="assets/gsap.min.js"></script><script src="assets/vehicle-state.js"></script><script src="assets/components.js"></script><style>html,body{margin:0;width:1080px;height:1920px;overflow:hidden;background:#06131e}*{box-sizing:border-box}#root{position:absolute;inset:0}</style></head><body>'''
root=HEAD+'''<div id="root" data-composition-id="main" data-start="0" data-duration="15" data-width="1080" data-height="1920" data-fps="30">
<video id="scene-layer" class="clip" data-start="0" data-duration="15" data-track-index="0" src="assets/animation-base-v3b.mp4" muted playsinline style="position:absolute;inset:0;width:1080px;height:1920px;object-fit:contain;z-index:0" data-layout-ignore></video>
<audio id="sound-mix" class="clip" data-start="0" data-duration="15" data-track-index="1" src="assets/mix.wav" data-volume="1"></audio>
<div id="hud" class="clip" data-composition-id="hud" data-composition-src="compositions/hud.html" data-start="0" data-duration="15" data-track-index="2" data-track-kind="graphics" data-width="1080" data-height="1920" style="z-index:2"></div>
<div id="captions" class="clip" data-composition-id="captions" data-composition-src="compositions/captions.html" data-start="0" data-duration="15" data-track-index="3" data-track-kind="captions" data-width="1080" data-height="1920" style="z-index:3"></div>
</div><script>const tl=gsap.timeline({paused:true});tl.to({t:0},{t:15,duration:15,ease:'none'},0);window.__timelines=window.__timelines||{};window.__timelines['main']=tl;</script></body></html>'''
(H/'index.html').write_text(root)
demo=HEAD+f'<style>{CSS}body{{background:#06131e}}</style><div id="root" data-composition-id="demo" data-start="0" data-duration="6" data-width="1080" data-height="1920" data-fps="30">'
demo+='<div id="demo-stage" class="clip" data-start="0" data-duration="6"><div style="position:absolute;left:108px;top:200px;font-family:FilmSans;font-weight:700;font-size:37px;color:#d4dde0">HYPERFRAMES · HUD STUDY</div><section id="demo-clock" class="panel clock" style="left:108px;top:350px;width:365px;height:154px"><div class="label">TIME</div><div id="demo-clock-value" class="value">02:17:00</div><div class="unit">AM</div></section><section id="demo-speed" class="panel compact" style="left:108px;top:660px;width:864px;height:250px"><div class="label">VEHICLE SPEED / SHARED MOTION STATE</div><div id="demo-speed-value" class="value" style="font-size:110px">18.0</div><div class="unit">km/h</div><div class="track"><div id="demo-speed-bar" class="fill"></div></div></section><section id="demo-gap" class="panel compact" style="left:108px;top:1090px;width:864px;height:250px"><div class="label">PURSUIT DISTANCE / WORLD POSITIONS</div><div id="demo-gap-value" class="value" style="font-size:110px">31.0</div><div class="unit">m</div><div class="track"><div id="demo-gap-bar" class="fill"></div></div></section></div></div>'
demo+="""<script>(()=>{const C=HFComponents,tl=gsap.timeline({paused:true}),clock=new C.DigitalClock('#demo-clock-value'),speed=new C.AnimatedCounter('#demo-speed-value',{initial:C.vehicleAt(0).speed_kmh,target:C.vehicleAt(15).speed_kmh,decimals:1}),bar=new C.AnimatedProgressBar('#demo-speed-bar',{max:140}),gap=new C.PursuitDistanceHUD('#demo-gap-value','#demo-gap-bar');['#demo-clock','#demo-speed','#demo-gap'].forEach((s,i)=>new C.CinematicHUDPanel(s).animate(tl,.06+i*.13,6));const p={t:0};function draw(t){const s=C.vehicleAt(t*2.5);clock.render(t*2.5);speed.render(s.speed_kmh);bar.render(s.speed_kmh);gap.render(s);}tl.to(p,{t:6,duration:6,ease:'none',onUpdate:()=>draw(p.t)},0);window.addEventListener('hf-seek',e=>draw(e.detail.time));draw(0);window.__timelines=window.__timelines||{};window.__timelines.demo=tl;})();</script></body></html>"""
D=R/'hyperframes-demo';D.mkdir(exist_ok=True);(D/'index.html').write_text(demo)
(H/'hyperframes.json').write_text(json.dumps({'$schema':'https://hyperframes.heygen.com/schema/hyperframes.json','paths':{'blocks':'compositions','components':'compositions/components','assets':'assets'},'media':{'autoProxy':False}},indent=2))
print('HyperFrames root/subcompositions/9component library/demo generated')
